using MediStock.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;
namespace MediStock.Pages.Predictions;[Authorize]public sealed class IndexModel(MediStockDbContext db):PageModel{[BindProperty(SupportsGet=true)]public int MedicineId{get;set;}[BindProperty(SupportsGet=true)]public int Days{get;set;}=7;public IReadOnlyList<SelectListItem>Medicines{get;private set;}=[];public int?PredictedQuantity{get;private set;}public int CurrentStock{get;private set;}
public async Task OnGetAsync(CancellationToken ct){Medicines=await db.Medicines.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.Name).Select(x=>new SelectListItem(x.Name,x.Id.ToString())).ToListAsync(ct);if(MedicineId==0&&Medicines.Count>0)MedicineId=int.Parse(Medicines[0].Value);if(Days is not 7 and not 30)Days=7;if(MedicineId<=0)return;var cutoff=DateTime.UtcNow.AddDays(-30);var units=await db.SaleItems.AsNoTracking().Where(x=>x.MedicineId==MedicineId&&x.Sale.Status=="Completed"&&x.Sale.SoldAtUtc>=cutoff).SumAsync(x=>(int?)x.Quantity,ct)??0;var averagePerDay=units/30d;PredictedQuantity=(int)Math.Ceiling(averagePerDay*Days);var today=DateTime.UtcNow.Date;CurrentStock=await db.StockBatches.AsNoTracking().Where(x=>x.MedicineId==MedicineId&&x.Quantity>0&&x.ExpiryDate>=today).SumAsync(x=>(int?)x.Quantity,ct)??0;}}
